                + ".atf-ui-action-sequence>summary{list-style:none!important;display:flex!important;align-items:center!important;padding:9px 12px!important;cursor:pointer!important;color:var(--atf-accent)!important;font-size:12px!important;line-height:16px!important}"
                + ".atf-ui-action-sequence>summary::-webkit-details-marker{display:none!important}.atf-ui-action-sequence>summary:before{content:'＋'!important;display:inline-flex!important;width:18px!important;align-items:center!important;justify-content:center!important;font-size:15px!important}.atf-ui-action-sequence[open]>summary:before{content:'−'!important}"
                + ".atf-ui-action-table-wrap{max-width:100%!important;overflow-x:auto!important;padding:0 8px 8px!important}.atf-ui-action-table{width:760px!important;min-width:760px!important;max-width:none!important;table-layout:fixed!important;border-collapse:collapse!important;font-size:12px!important;line-height:16px!important}"
                + ".atf-ui-action-table th,.atf-ui-action-table td{border:1px solid var(--atf-border)!important;padding:5px 6px!important;text-align:left!important;vertical-align:top!important;overflow-wrap:anywhere!important;word-break:break-word!important}"
                + ".atf-ui-action-table th{white-space:nowrap!important;overflow-wrap:normal!important;word-break:normal!important;color:var(--atf-muted)!important;background:" + AtfReportColors.WHITE_024 + "!important;font-size:10.5px!important;font-weight:500!important}"
                + ".atf-ui-action-table td{color:var(--atf-table-text)!important;background:var(--atf-surface)!important}"
                + ".atf-ui-action-table th:nth-child(1),.atf-ui-action-table td:nth-child(1){width:42px!important;min-width:42px!important;max-width:42px!important;text-align:center!important;white-space:nowrap!important}"
                + ".atf-ui-action-table th:nth-child(2),.atf-ui-action-table td:nth-child(2){width:125px!important;min-width:125px!important;max-width:125px!important;color:var(--atf-accent)!important}"
                + ".atf-ui-action-table th:nth-child(3),.atf-ui-action-table td:nth-child(3){width:160px!important;min-width:160px!important;max-width:160px!important}"
                + ".atf-ui-action-table th:nth-child(4),.atf-ui-action-table td:nth-child(4){width:145px!important;min-width:145px!important;max-width:145px!important}"
                + ".atf-ui-action-table th:nth-child(5),.atf-ui-action-table td:nth-child(5){width:150px!important;min-width:150px!important;max-width:150px!important}"
                + ".atf-ui-action-table th:nth-child(6),.atf-ui-action-table td:nth-child(6){width:68px!important;min-width:68px!important;max-width:68px!important;white-space:nowrap!important}"
                + ".atf-ui-action-table th:nth-child(7),.atf-ui-action-table td:nth-child(7){width:70px!important;min-width:70px!important;max-width:70px!important;text-align:center!important;white-space:nowrap!important}"
                 + ".atf-ui-action-result{display:inline-block!important;padding:0!important;border:0!important;border-radius:0!important;background:transparent!important;color:inherit!important;font-size:14px!important;line-height:1!important;font-weight:400!important}"
                 + ".atf-ui-action-result-pass,.atf-ui-action-result-warning,.atf-ui-action-result-fail,.atf-ui-action-result-skip,.atf-ui-action-result-info{background:transparent!important;color:inherit!important}"
                + "@media (max-width:700px){.atf-ui-action-sequence{margin:7px 0!important;border-radius:8px!important}.atf-ui-action-sequence>summary{padding:7px 8px!important;font-size:11px!important;line-height:14px!important}.atf-ui-action-table-wrap{padding:0 4px 4px!important}.atf-ui-action-table{font-size:11px!important;line-height:14px!important;min-width:760px!important;width:760px!important;table-layout:fixed!important}.atf-ui-action-table th,.atf-ui-action-table td{padding:4px 5px!important}.atf-ui-action-result{font-size:13px!important}}"
                 + ".atf-ui-action-screenshot{display:flex!important;justify-content:flex-start!important;align-items:flex-end!important;text-align:left!important;vertical-align:bottom!important;margin:0 8px 8px!important;padding:4px 0 0!important;max-width:100%!important;overflow:auto!important}"
                 + ".atf-ui-action-screenshot-link{display:inline-flex!important;align-items:center!important;align-self:flex-end!important;justify-content:flex-start!important;line-height:16px!important;min-height:16px!important;vertical-align:bottom!important;text-decoration:none!important}"
                 + ".atf-ui-action-screenshot-link .badge-gradient-primary{display:inline-flex!important;align-items:center!important;justify-content:center!important;line-height:16px!important;min-height:16px!important;margin:0!important;vertical-align:middle!important}"
                + ".atf-ui-action-screenshot-link:hover{filter:brightness(1.08)!important}"
                + ".step-detail{margin:0!important;border:1px solid var(--atf-border)!important;border-radius:12px!important;overflow:hidden!important;background:var(--atf-dark)!important}"
                + ".step-detail>summary{list-style:none!important;display:flex!important;align-items:center!important;gap:8px!important;padding:10px 12px!important;color:var(--atf-accent)!important;cursor:pointer!important}"
                + ".step-detail>summary::-webkit-details-marker{display:none!important}.step-detail .se-toggle{display:none!important}"
                + ".atf-disclosure-glyph{display:inline-flex!important;flex:0 0 18px!important;width:18px!important;height:18px!important;align-items:center!important;justify-content:center!important;color:var(--atf-accent)!important;font-size:17px!important;font-weight:500!important;line-height:18px!important}"
                + ".atf-disclosure-glyph:before{content:'＋'!important}.step-detail[open] .atf-disclosure-glyph:before{content:'−'!important}"
                + ".step-detail .se-title{color:var(--atf-accent)!important}.step-detail .body{padding:0 10px 10px!important}";
